/* eslint-disable @typescript-eslint/unbound-method */
import { afterEach, beforeEach, describe, expect, it, jest } from '@jest/globals';
import { EconomyService } from '../../services/economyService';
import { economyRepository } from '../../repositories/economyRepository';
import type { EconomyBalance, EconomySettings, EconomyTransaction } from '../../database/schema';

jest.mock('../../repositories/economyRepository', () => ({
  economyRepository: {
    getBalance: jest.fn(),
    ensureSettings: jest.fn(),
    createBalance: jest.fn(),
    addToBalance: jest.fn(),
    createTransaction: jest.fn(),
    transferBalance: jest.fn(),
    isOnCooldown: jest.fn(),
    getCooldown: jest.fn(),
    setCooldown: jest.fn(),
    updateBalance: jest.fn(),
    updateSettings: jest.fn(),
    getTopBalances: jest.fn(),
    getShopItem: jest.fn(),
    getUserItem: jest.fn(),
    addUserItem: jest.fn(),
    updateUserItem: jest.fn(),
    updateShopItem: jest.fn(),
    hasActiveProtection: jest.fn(),
    updateGamblingStats: jest.fn(),
    getRecentGambles: jest.fn(),
  },
}));

const mockRepository = economyRepository as jest.Mocked<typeof economyRepository>;

const createBalance = (overrides: Partial<EconomyBalance> = {}): EconomyBalance =>
  ({
    userId: 'user-1',
    guildId: 'guild-1',
    balance: 1000,
    bankBalance: 0,
    totalEarned: 0,
    totalSpent: 0,
    totalGambled: 0,
    createdAt: new Date(),
    updatedAt: new Date(),
    ...overrides,
  }) as EconomyBalance;

const createSettings = (overrides: Partial<EconomySettings> = {}): EconomySettings =>
  ({
    guildId: 'guild-1',
    currencySymbol: '💰',
    currencyName: 'coins',
    startingBalance: 100,
    dailyAmount: 100,
    dailyStreak: true,
    dailyStreakBonus: 10,
    workMinAmount: 50,
    workMaxAmount: 200,
    workCooldown: 3600,
    robEnabled: true,
    robMinAmount: 100,
    robSuccessRate: 50,
    robCooldown: 86400,
    robProtectionCost: 1000,
    robProtectionDuration: 86400,
    maxBet: 10000,
    minBet: 10,
    createdAt: new Date(),
    updatedAt: new Date(),
    ...overrides,
  }) as EconomySettings;

const createTransaction = (overrides: Partial<EconomyTransaction> = {}): EconomyTransaction =>
  ({
    id: 'txn-1',
    userId: 'user-1',
    guildId: 'guild-1',
    type: 'test',
    amount: 100,
    description: 'Test transaction',
    metadata: null,
    relatedUserId: null,
    createdAt: new Date(),
    ...overrides,
  }) as EconomyTransaction;

describe('EconomyService', () => {
  let service: EconomyService;

  beforeEach(() => {
    jest.useFakeTimers();
    jest.setSystemTime(new Date('2024-01-01T00:00:00.000Z'));
    jest.clearAllMocks();
    service = new EconomyService();
    mockRepository.ensureSettings.mockResolvedValue(createSettings());
  });

  afterEach(() => {
    jest.useRealTimers();
  });

  describe('getOrCreateBalance', () => {
    it('returns existing balance when present', async () => {
      const balance = createBalance({ balance: 500 });
      mockRepository.getBalance.mockResolvedValueOnce(balance);

      const result = await service.getOrCreateBalance('user-1', 'guild-1');

      expect(result).toBe(balance);
      expect(mockRepository.createBalance).not.toHaveBeenCalled();
    });

    it('creates a new balance when missing', async () => {
      const settings = createSettings({ startingBalance: 250 });
      const newBalance = createBalance({ balance: 250 });

      mockRepository.getBalance.mockResolvedValueOnce(null);
      mockRepository.ensureSettings.mockResolvedValueOnce(settings);
      mockRepository.createBalance.mockResolvedValueOnce(newBalance);

      const result = await service.getOrCreateBalance('user-1', 'guild-1');

      expect(result).toEqual(newBalance);
      expect(mockRepository.createBalance).toHaveBeenCalledWith({
        userId: 'user-1',
        guildId: 'guild-1',
        balance: 250,
      });
    });
  });

  describe('addMoney', () => {
    it('adds funds and records transaction', async () => {
      const balance = createBalance({ balance: 500 });
      const updatedBalance = createBalance({ balance: 700 });
      const transaction = createTransaction({ amount: 200, type: 'reward' });

      mockRepository.getBalance.mockResolvedValue(balance);
      mockRepository.addToBalance.mockResolvedValueOnce(updatedBalance);
      mockRepository.createTransaction.mockResolvedValueOnce(transaction);

      const result = await service.addMoney('user-1', 'guild-1', 200, 'reward', 'Weekly reward');

      expect(result.success).toBe(true);
      expect(result.balance).toEqual(updatedBalance);
      expect(result.transaction).toEqual(transaction);
      expect(mockRepository.createTransaction).toHaveBeenCalledWith(
        expect.objectContaining({
          userId: 'user-1',
          guildId: 'guild-1',
          type: 'reward',
          amount: 200,
          description: 'Weekly reward',
        })
      );
    });

    it('returns failure when balance update fails', async () => {
      mockRepository.getBalance.mockResolvedValue(createBalance());
      mockRepository.addToBalance.mockResolvedValueOnce(null);

      const result = await service.addMoney('user-1', 'guild-1', 50, 'reward');

      expect(result.success).toBe(false);
      expect(result.error).toBe('Failed to update balance');
    });
  });

  describe('transferMoney', () => {
    it('prevents transfer when sender has insufficient funds', async () => {
      mockRepository.getBalance.mockResolvedValueOnce(createBalance({ balance: 100 }));

      const result = await service.transferMoney('from-user', 'to-user', 'guild-1', 200);

      expect(result.success).toBe(false);
      expect(result.error).toBe('Insufficient funds');
    });

    it('transfers funds between users', async () => {
      const fromBalance = createBalance({ userId: 'from-user', balance: 500 });
      const toBalance = createBalance({ userId: 'to-user', balance: 300 });
      const deductedBalance = createBalance({ userId: 'from-user', balance: 300 });
      const creditedBalance = createBalance({ userId: 'to-user', balance: 500 });
      const debitTransaction = createTransaction({
        id: 'txn-1',
        userId: 'from-user',
        amount: -200,
      });
      const creditTransaction = createTransaction({ id: 'txn-2', userId: 'to-user', amount: 200 });

      mockRepository.getBalance
        .mockResolvedValueOnce(fromBalance) // initial sender balance
        .mockResolvedValueOnce(fromBalance) // addMoney -> getOrCreateBalance (sender)
        .mockResolvedValueOnce(toBalance) // addMoney -> getOrCreateBalance (receiver)
        .mockResolvedValue(toBalance); // fallback for any additional calls

      mockRepository.addToBalance
        .mockResolvedValueOnce(deductedBalance)
        .mockResolvedValueOnce(creditedBalance);

      mockRepository.createTransaction
        .mockResolvedValueOnce(debitTransaction)
        .mockResolvedValueOnce(creditTransaction);

      const result = await service.transferMoney('from-user', 'to-user', 'guild-1', 200);

      expect(result.success).toBe(true);
      expect(mockRepository.addToBalance).toHaveBeenNthCalledWith(1, 'from-user', 'guild-1', -200);
      expect(mockRepository.addToBalance).toHaveBeenNthCalledWith(2, 'to-user', 'guild-1', 200);
    });
  });

  describe('claimDaily', () => {
    it('returns cooldown message when user is on cooldown', async () => {
      const nextAvailable = new Date(Date.now() + 3_600_000);
      mockRepository.isOnCooldown.mockResolvedValueOnce(true);
      mockRepository.getCooldown.mockResolvedValueOnce({
        userId: 'user-1',
        guildId: 'guild-1',
        commandType: 'daily',
        lastUsed: new Date(),
        nextAvailable,
      } as any);

      const result = await service.claimDaily('user-1', 'guild-1');

      expect(result.success).toBe(false);
      expect(result.error).toContain('You can claim your daily reward in');
    });

    it('awards daily reward when available', async () => {
      const balance = createBalance({ balance: 1000 });
      const updatedBalance = createBalance({ balance: 1100 });
      const transaction = createTransaction({ amount: 100, type: 'daily' });

      mockRepository.isOnCooldown.mockResolvedValueOnce(false);
      mockRepository.getCooldown.mockResolvedValueOnce(null);
      mockRepository.getBalance.mockResolvedValue(balance);
      mockRepository.addToBalance.mockResolvedValueOnce(updatedBalance);
      mockRepository.createTransaction.mockResolvedValueOnce(transaction);
      mockRepository.setCooldown.mockResolvedValueOnce({} as any);

      const result = await service.claimDaily('user-1', 'guild-1');

      expect(result.success).toBe(true);
      expect(result.balance).toEqual(updatedBalance);
      expect(result.transaction?.type).toBe('daily');
      expect(mockRepository.setCooldown).toHaveBeenCalledWith(
        expect.objectContaining({
          userId: 'user-1',
          guildId: 'guild-1',
          commandType: 'daily',
        })
      );
    });
  });

  describe('work', () => {
    it('prevents work when on cooldown', async () => {
      mockRepository.isOnCooldown.mockResolvedValueOnce(true);
      mockRepository.getCooldown.mockResolvedValueOnce({
        userId: 'user-1',
        guildId: 'guild-1',
        commandType: 'work',
        lastUsed: new Date(),
        nextAvailable: new Date(Date.now() + 10_000),
      } as any);

      const result = await service.work('user-1', 'guild-1');

      expect(result.success).toBe(false);
      expect(result.error).toContain('You can work again in');
    });

    it('awards work payout within configured range', async () => {
      const balance = createBalance({ balance: 800 });
      const updatedBalance = createBalance({ balance: 950 });
      const transaction = createTransaction({ amount: 150, type: 'work', description: 'Job desc' });

      mockRepository.isOnCooldown.mockResolvedValueOnce(false);
      mockRepository.getBalance.mockResolvedValue(balance);
      mockRepository.addToBalance.mockResolvedValueOnce(updatedBalance);
      mockRepository.createTransaction.mockResolvedValueOnce(transaction);
      mockRepository.setCooldown.mockResolvedValueOnce({} as any);

      jest.spyOn(Math, 'random').mockReturnValueOnce(0.5).mockReturnValueOnce(0);

      const result = await service.work('user-1', 'guild-1');

      expect(result.success).toBe(true);
      expect(result.transaction?.type).toBe('work');
      (Math.random as jest.Mock).mockRestore();
    });
  });

  describe('rob', () => {
    it('aborts when robbing is disabled', async () => {
      mockRepository.ensureSettings.mockResolvedValueOnce(createSettings({ robEnabled: false }));

      const result = await service.rob('robber', 'victim', 'guild-1');

      expect(result.success).toBe(false);
      expect(result.error).toBe('Robbing is disabled in this server');
    });

    it('respects protection items', async () => {
      mockRepository.ensureSettings.mockResolvedValueOnce(createSettings());
      mockRepository.isOnCooldown.mockResolvedValueOnce(false);
      mockRepository.hasActiveProtection.mockResolvedValueOnce(true);
      mockRepository.setCooldown.mockResolvedValueOnce({} as any);

      const result = await service.rob('robber', 'victim', 'guild-1');

      expect(result.success).toBe(false);
      expect(result.protected).toBe(true);
    });
  });
});

import { afterEach, beforeEach, describe, expect, it, jest } from '@jest/globals';
import { WarningService } from '../../services/warningService';
import { warningRepository } from '../../repositories/warningRepository';
import { auditLogger } from '../../security/audit';
import { ensureUserAndGuildExist } from '../../utils/userUtils';
import { createMockGuild, createMockUser } from '../../test-utils/mockDiscord';
import type { Guild, User } from 'discord.js';

jest.mock('../../repositories/warningRepository', () => ({
  warningRepository: {
    createWarning: jest.fn(),
    getWarningById: jest.fn(),
    updateWarning: jest.fn(),
    getUserWarningStats: jest.fn(),
    getActiveAutomations: jest.fn(),
    updateAutomationLastTriggered: jest.fn(),
  },
}));

jest.mock('../../security/audit', () => ({
  auditLogger: {
    logAction: jest.fn(),
  },
}));

jest.mock('../../utils/userUtils', () => ({
  ensureUserAndGuildExist: jest.fn(),
}));

jest.mock('../../i18n', () => ({
  t: (key: string, params?: Record<string, unknown>) =>
    `${key}${params ? `:${JSON.stringify(params)}` : ''}`,
}));

const mockRepo = warningRepository as jest.Mocked<typeof warningRepository>;
const mockAudit = auditLogger as jest.Mocked<typeof auditLogger>;
const mockEnsure = ensureUserAndGuildExist as jest.Mock;

const createWarningRecord = (overrides: Record<string, unknown> = {}) => ({
  id: 1,
  warnId: 'W123',
  guildId: 'guild-1',
  userId: 'user-1',
  moderatorId: 'mod-1',
  title: 'Test warning',
  description: 'Test description',
  level: 1,
  proof: null,
  active: true,
  editedAt: null,
  editedBy: null,
  createdAt: new Date(),
  updatedAt: new Date(),
  ...overrides,
});

const createAutomation = (overrides: Record<string, unknown> = {}) => ({
  id: 1,
  automationId: 'AUTO1',
  guildId: 'guild-1',
  name: 'Auto warn',
  description: null,
  triggerType: 'warn_count',
  triggerValue: 3,
  actions: [{ type: 'timeout', duration: 3_600_000 }],
  enabled: true,
  createdBy: 'mod-1',
  lastTriggeredAt: null,
  createdAt: new Date(),
  updatedAt: new Date(),
  ...overrides,
});

describe('WarningService', () => {
  let service: WarningService;
  let guild: Guild;
  let user: User;
  let moderator: User;

  beforeEach(() => {
    jest.clearAllMocks();
    service = new WarningService();
    guild = createMockGuild();
    user = createMockUser();
    moderator = createMockUser({ id: 'mod-1' } as any);
  });

  afterEach(() => {
    jest.resetModules();
  });

  describe('createWarning', () => {
    it('creates a warning and logs the action', async () => {
      const warning = createWarningRecord();
      mockRepo.createWarning.mockResolvedValueOnce(warning);
      jest.spyOn(service, 'checkAutomations').mockResolvedValueOnce();

      const result = await service.createWarning(
        guild,
        user,
        moderator,
        'Test warning',
        'Details',
        2
      );

      expect(mockEnsure).toHaveBeenCalledTimes(2);
      expect(mockRepo.createWarning).toHaveBeenCalledWith(
        expect.objectContaining({
          guildId: guild.id,
          userId: user.id,
          moderatorId: moderator.id,
          title: 'Test warning',
          description: 'Details',
          level: 2,
        })
      );
      expect(mockAudit.logAction).toHaveBeenCalledWith(
        expect.objectContaining({
          action: 'WARN_CREATE',
          userId: moderator.id,
          guildId: guild.id,
          targetId: user.id,
        })
      );
      expect(result).toEqual(warning);
    });
  });

  describe('editWarning', () => {
    it('updates a warning when it exists', async () => {
      const warning = createWarningRecord();
      const updated = createWarningRecord({ title: 'Updated title' });

      mockRepo.getWarningById.mockResolvedValueOnce(warning);
      mockRepo.updateWarning.mockResolvedValueOnce(updated as any);

      const result = await service.editWarning(
        'W123',
        'Updated title',
        'New description',
        moderator
      );

      expect(result).toEqual(updated);
      expect(mockRepo.updateWarning).toHaveBeenCalledWith('W123', {
        title: 'Updated title',
        description: 'New description',
        editedBy: moderator.id,
      });
      expect(mockAudit.logAction).toHaveBeenCalled();
    });

    it('throws when warning does not exist', async () => {
      mockRepo.getWarningById.mockResolvedValueOnce(null as any);

      await expect(
        service.editWarning('missing', 'Updated title', null, moderator)
      ).rejects.toThrow('Warning not found');
    });
  });

  describe('checkAutomations', () => {
    it('triggers automations when threshold met', async () => {
      mockRepo.getUserWarningStats.mockResolvedValueOnce({ count: 3, totalLevel: 6 });
      mockRepo.getActiveAutomations.mockResolvedValueOnce([
        createAutomation({
          triggerType: 'warn_count',
          triggerValue: 2,
          actions: [{ type: 'ban' }],
        }),
      ]);

      await service.checkAutomations(guild, user);

      expect(mockRepo.updateAutomationLastTriggered).toHaveBeenCalled();
    });

    it('skips automations below threshold', async () => {
      mockRepo.getUserWarningStats.mockResolvedValueOnce({ count: 1, totalLevel: 1 });
      mockRepo.getActiveAutomations.mockResolvedValueOnce([
        createAutomation({
          triggerType: 'warn_count',
          triggerValue: 5,
        }),
      ]);

      await service.checkAutomations(guild, user);

      expect(mockRepo.updateAutomationLastTriggered).not.toHaveBeenCalled();
    });
  });
});

import { autoModService } from '../../../services/autoModService';
import { autoModRepository } from '../../../repositories/autoModRepository';
import { Message } from 'discord.js';

jest.mock('../../../repositories/autoModRepository');
jest.mock('../../../utils/logger');

describe('AutoModService', () => {
  beforeEach(() => {
    jest.clearAllMocks();
  });

  describe('evaluateMessage', () => {
    it('should return false if message is not in a guild or author is bot', async () => {
      const mockMessage = {
        guild: null,
        author: { bot: true },
      } as unknown as Message;

      const result = await autoModService.evaluateMessage(mockMessage);
      expect(result).toBe(false);
    });

    it('should return false if no rules match', async () => {
      const mockMessage = {
        guild: { id: 'guild123' },
        author: { bot: false, id: 'user123' },
        member: { roles: { cache: { has: () => false } } },
        channel: { id: 'channel123' },
        content: 'hello world',
        mentions: { users: { size: 0 }, roles: { size: 0 } },
        attachments: { size: 0 },
      } as unknown as Message;

      (autoModRepository.getRulesByEvent as jest.Mock).mockResolvedValue([
        {
          id: 'rule1',
          triggerType: 'KEYWORD',
          triggerMetadata: { keywords: ['badword'] },
          actions: [],
          exemptChannels: [],
          exemptRoles: [],
        },
      ]);

      const result = await autoModService.evaluateMessage(mockMessage);
      expect(result).toBe(false);
    });

    it('should return true and execute actions if rule matches', async () => {
      const mockDelete = jest.fn().mockResolvedValue(true);
      const mockMessage = {
        id: 'msg123',
        guild: { id: 'guild123' },
        author: { bot: false, id: 'user123' },
        member: { roles: { cache: { has: () => false } } },
        channel: { id: 'channel123', send: jest.fn().mockResolvedValue(true) },
        content: 'this is a badword',
        deletable: true,
        delete: mockDelete,
        mentions: { users: { size: 0 }, roles: { size: 0 } },
        attachments: { size: 0 },
      } as unknown as Message;

      (autoModRepository.getRulesByEvent as jest.Mock).mockResolvedValue([
        {
          id: 'rule1',
          triggerType: 'KEYWORD',
          triggerMetadata: { keywords: ['badword'] },
          actions: [{ type: 'DELETE_MESSAGE' }, { type: 'WARN_USER' }],
          exemptChannels: [],
          exemptRoles: [],
        },
      ]);

      const result = await autoModService.evaluateMessage(mockMessage);
      expect(result).toBe(true);
      expect(mockDelete).toHaveBeenCalled();
    });
  });

  describe('quarantineUser', () => {
    it('should quarantine a user successfully', async () => {
      const mockVaultRecord = {
        id: 'vault1',
        guildId: 'guild123',
        userId: 'user123',
        originalRoles: ['role1'],
        reason: 'Spam',
        quarantinedAt: new Date(),
      };

      (autoModRepository.getQuarantineStatus as jest.Mock).mockResolvedValue(null);
      (autoModRepository.quarantineUser as jest.Mock).mockResolvedValue(mockVaultRecord);

      const result = await autoModService.quarantineUser(
        'guild123',
        'user123',
        null,
        'Spam',
        'admin123'
      );
      expect(result).toEqual(mockVaultRecord);
      expect(autoModRepository.quarantineUser).toHaveBeenCalledWith({
        guildId: 'guild123',
        userId: 'user123',
        originalRoles: [],
        reason: 'Spam',
        jailedBy: 'admin123',
      });
    });
  });
});

import { describe, expect, it, jest, beforeEach } from '@jest/globals';
import { crossShardService } from '../../../services/crossShardService';

describe('CrossShardService', () => {
  let mockClient: any;

  beforeEach(() => {
    mockClient = {
      ws: {
        status: 0,
        ping: 35,
        shards: new Map([[0, { id: 0, status: 0, ping: 35 }]]),
      },
      uptime: 123456,
      guilds: {
        cache: new Map([
          [
            '123456789012345678',
            {
              id: '123456789012345678',
              name: 'Guild 1',
              icon: null,
              memberCount: 100,
              ownerId: '999999',
              joinedAt: new Date('2024-01-01'),
              banner: null,
              description: 'Test guild 1',
              features: new Set(['COMMUNITY']),
              large: false,
              vanityURLCode: null,
              members: {
                cache: new Map([
                  [
                    '999999',
                    { id: '999999', user: { bot: false }, presence: { status: 'online' } },
                  ],
                ]),
              },
              channels: { cache: new Map([['channel1', { size: 1 }]]) },
            },
          ],
        ]),
      },
      users: {
        cache: new Map([
          [
            '999999',
            {
              id: '999999',
              username: 'testuser',
              discriminator: '0000',
              avatar: null,
              tag: 'testuser#0000',
              bot: false,
            },
          ],
        ]),
        fetch: jest.fn(),
      },
      shard: null,
    };
  });

  describe('isSharded', () => {
    it('returns false when client.shard is null', () => {
      expect(crossShardService.isSharded(mockClient)).toBe(false);
    });

    it('returns true when client.shard is present', () => {
      mockClient.shard = { count: 2, ids: [0] };
      expect(crossShardService.isSharded(mockClient)).toBe(true);
    });
  });

  describe('getShardIdForGuild', () => {
    it('correctly calculates shard ID based on guild snowflake', () => {
      const guildId = '381880193251475464';
      const shardId = crossShardService.getShardIdForGuild(guildId, 4);
      expect(typeof shardId).toBe('number');
      expect(shardId).toBeGreaterThanOrEqual(0);
      expect(shardId).toBeLessThan(4);
    });

    it('handles invalid guild IDs gracefully', () => {
      expect(crossShardService.getShardIdForGuild('invalid', 4)).toBe(0);
    });
  });

  describe('getTotalGuildsCount', () => {
    it('returns local cache size when not sharded', async () => {
      const count = await crossShardService.getTotalGuildsCount(mockClient);
      expect(count).toBe(1);
    });

    it('sums guild counts across shards when sharded', async () => {
      mockClient.shard = {
        count: 2,
        ids: [0],
        fetchClientValues: jest.fn().mockResolvedValue([10, 15] as never),
      };

      const count = await crossShardService.getTotalGuildsCount(mockClient);
      expect(count).toBe(25);
    });
  });

  describe('getTotalUsersCount', () => {
    it('calculates total members from local cache when not sharded', async () => {
      const count = await crossShardService.getTotalUsersCount(mockClient);
      expect(count).toBe(100);
    });

    it('sums user counts across shards when sharded', async () => {
      mockClient.shard = {
        count: 2,
        ids: [0],
        broadcastEval: jest.fn().mockResolvedValue([100, 200] as never),
      };

      const count = await crossShardService.getTotalUsersCount(mockClient);
      expect(count).toBe(300);
    });
  });

  describe('fetchGuild', () => {
    it('fetches guild from local cache if present', async () => {
      const guild = await crossShardService.fetchGuild(mockClient, '123456789012345678');
      expect(guild).not.toBeNull();
      expect(guild?.name).toBe('Guild 1');
      expect(guild?.memberCount).toBe(100);
    });

    it('returns null if guild not found in non-sharded mode', async () => {
      const guild = await crossShardService.fetchGuild(mockClient, '000000000000000000');
      expect(guild).toBeNull();
    });

    it('queries other shards when sharded and guild is not in local cache', async () => {
      mockClient.shard = {
        count: 2,
        ids: [0],
        broadcastEval: jest.fn().mockResolvedValue([
          null,
          {
            id: '888888888888888888',
            name: 'Remote Guild',
            icon: null,
            memberCount: 50,
            ownerId: '111111',
            shardId: 1,
          },
        ] as never),
      };

      const guild = await crossShardService.fetchGuild(mockClient, '888888888888888888');
      expect(guild).not.toBeNull();
      expect(guild?.name).toBe('Remote Guild');
      expect(guild?.shardId).toBe(1);
    });
  });

