import {
  guilds as guildsTable,
  guildSettings,
  economyBalances,
  economyShopItems,
  economySettings,
  modCases,
  modLogSettings,
  tickets,
  ticketPanels,
  giveaways,
  giveawayEntries,
  xpRewards,
  auditLogs,
  userXp,
} from '../../database/schema';
import { eq, desc, and, sql, gte } from 'drizzle-orm';
