router.get('/:guildId/members', async (req: Request, res: Response): Promise<Response | void> => {
  const { guildId } = req.params;

  try {
    let guild: Guild | SerializedGuild | null | undefined = client.guilds.cache.get(guildId);
    if (!guild) {
      guild = await crossShardService.fetchGuild(client, guildId);
    }

    if (!guild) {
      return res.status(404).json({
        error: 'Not Found',
        message: 'Guild not found',
      });
    }

    const members = (guild as Guild).members?.cache;
    const onlineMembers = members
      ? members.filter((m: GuildMember) => m.presence?.status !== 'offline')
      : [];
    const bots = members ? members.filter((m: GuildMember) => m.user?.bot) : [];
    const humans = members ? members.filter((m: GuildMember) => !m.user?.bot) : [];

    const response = {
      members: members
        ? Array.from(members.values())
            .slice(0, 20)
            .map((m: GuildMember) => ({
              id: m.id,
              username: m.user?.username,
              discriminator: m.user?.discriminator,
              nickname: m.nickname,
              roles: m.roles?.cache ? Array.from(m.roles.cache.keys()) : [],
              joinedAt: m.joinedAt?.toISOString?.() || null,
              isBot: Boolean(m.user?.bot),
            }))
        : [],
      stats: {
        total: guild.memberCount || 0,
        online:
          typeof onlineMembers === 'number' ? onlineMembers : onlineMembers?.size || 0,
        bots: typeof bots === 'number' ? bots : bots?.size || 0,
        humans: typeof humans === 'number' ? humans : humans?.size || 0,
      },
    };

    res.json(response);
  } catch (error) {
    logger.error('Error fetching guild members:', error);
    res.status(500).json({
      error: 'Internal Server Error',
      message: 'Failed to fetch members',
    });
  }
});

