    await interaction.editReply({
      content: `✅ Department \`${departmentId}\` removed from panel **${panelCustomId}**.`,
    });
  } catch (error: any) {
    await interaction.editReply({
      content: t('common.error', { error: t(error.message, { defaultValue: error.message }) }),
    });
  }
}

